/**
 * vendor/pdf.min.js
 * Standalone PDF.js loader wrapper for Chrome Extension on-device PDF extraction.
 */
(function(global) {
  'use strict';
  if (!global.pdfjsLib) {
    global.pdfjsLib = {
      GlobalWorkerOptions: { workerSrc: '' },
      getDocument: function(params) {
        return {
          promise: (async function() {
            if (typeof global.extractPdfText === 'function') {
              const res = global.extractPdfText(params.data);
              return {
                numPages: res.pages ? res.pages.length : 1,
                getPage: async function(i) {
                  const pageText = (res.pages && res.pages[i - 1]) ? res.pages[i - 1].text : res.fullText;
                  return {
                    getTextContent: async function() {
                      return { items: [{ str: pageText }] };
                    }
                  };
                }
              };
            }
            throw new Error('PDF_JS_WORKER_UNAVAILABLE');
          })()
        };
      }
    };
  }
})(typeof self !== 'undefined' ? self : globalThis);
